        has_location = bool(row.get("project_name") or row.get("workflow_name") or row.get("task_name"))
        if has_location and confidence in {"high", "medium"} and info != "no-match":
            return True
        sql = candidate_sql(row)
        if not sql:
            continue
        comparison = compare_sql(source_sql, sql)
        if comparison["exact"] or comparison["template_exact"] or comparison["contains"] or comparison["template_contains"]:
            return True
    return False


GIT_SEARCH_ACCOUNTS = {"e_load", "e_ds_strategy"}


