def collect_candidate_strings(value, depth=0, seen=None):
    if seen is None:
        seen = set()
    if value is None or depth > 8:
        return []
    if isinstance(value, (str, int, float)):
        return [str(value)]
    if not isinstance(value, (dict, list)) or id(value) in seen:
        return []
    seen.add(id(value))
    values = []
    children = value if isinstance(value, list) else value.values()
    for child in children:
        values.extend(collect_candidate_strings(child, depth + 1, seen))
        if len(values) >= 200:
            break
    return values[:200]


def candidate_file_terms(rows):
    terms = set()
    for row in rows:
        for value in collect_candidate_strings(row):
            for match in re.findall(r"(?:^|[/\s'\"])([\w.-]+\.(?:sql|hql|py|sh|bash))(?:$|[\s'\"])", value, flags=re.I):
                if len(match) >= 4:
                    terms.add(match)
    return terms


def sql_search_terms(source_sql):
    terms = []
    seen = set()
    for raw_line in text(source_sql).splitlines():
        line = " ".join(raw_line.split()).strip()
        if len(line) < 16:
            continue
        if not re.search(r"\b(?:create|insert|select|from|join|where|group\s+by|update|delete)\b", line, flags=re.I):
            continue
        line = line[:240]
        lowered = line.lower()
        if lowered not in seen:
            seen.add(lowered)
            terms.append(line)
    for table in extract_tables(source_sql):
        if table.lower() not in seen:
            seen.add(table.lower())
            terms.append(table)
    return terms[:4]


def find_files_with_rg(root, terms):
    rg = shutil.which("rg")
    if not rg:
        return []
    paths = []
    seen = set()
    for term in terms:
        if time.monotonic() >= SEARCH_DEADLINE:
            break
        command = [
            rg,
            "-l",
            "--fixed-strings",
            "--no-messages",
            "--glob",
            "*.sql",
            "--glob",
            "*.hql",
            "--glob",
            "*.py",
            "--glob",
            "*.sh",
            "--glob",
            "*.bash",
            term,
            str(root),
        ]
        try:
            remaining = max(0.2, SEARCH_DEADLINE - time.monotonic())
            result = subprocess.run(
                command,
                capture_output=True,
                text=True,
                timeout=min(RG_SEARCH_TIMEOUT_SECONDS, remaining),
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired):
            continue
        for raw_path in result.stdout.splitlines():
            path = Path(raw_path).resolve()
            try:
                path.relative_to(root)
            except ValueError:
                continue
            if path not in seen and path.is_file():
                seen.add(path)
                paths.append(path)
                if len(paths) >= MAX_SEARCH_FILES:
                    return paths
    return paths


def find_files_with_python(root, source_sql, terms):
    lowered_terms = [term.lower() for term in terms if term]
    if not lowered_terms:
        return []
    paths = []
    scanned = 0
    for path in root.rglob("*"):
        if (
            len(paths) >= MAX_SEARCH_FILES
            or scanned >= MAX_PYTHON_SCANNED_FILES
            or time.monotonic() >= SEARCH_DEADLINE
        ):
            break
        if not path.is_file() or path.suffix.lower() not in ALLOWED_SUFFIXES:
            continue
        scanned += 1
        try:
            if path.stat().st_size > MAX_FILE_BYTES:
                continue
            content = path.read_text(encoding="utf-8", errors="ignore").lower()
        except OSError:
            continue
        comparison = compare_sql(source_sql, content)
        sql_matched = bool(
            comparison["exact"]
            or comparison["template_exact"]
            or comparison["contains"]
            or comparison["template_contains"]
            or comparison["table_overlap"] > 0
        )
        if sql_matched or any(term in content or term in path.name.lower() for term in lowered_terms):
            paths.append(path.resolve())
    return paths


def read_evidence(root, paths, source_sql):
    evidence = []
