        return [], {"raw_candidate_count": 0, "ds_pid": pid}
    query_limit = min(max(max_results * 20, 200), 500)
    script_expressions = []
    for expression in (matcher.SCRIPT_CONTENT_EXPR, "COALESCE(td.task_params, '')"):
        if expression and expression not in script_expressions:
            script_expressions.append(expression)
    raw_candidate_count = 0
    lookup_modes = []
    for script_expression in script_expressions:
        clauses = [
            f"LOWER({script_expression}) LIKE '%{sql_like_literal(term)}%' ESCAPE '\\\\'"
            for term in all_terms
        ]
        script_filter_sql = "AND (" + " OR ".join(clauses) + ")"
        sql = matcher.DS_TASK_CANDIDATE_SQL_TEMPLATE.format(
            limit=query_limit,
            script_content_expr=script_expression,
            script_filter_sql=script_filter_sql,
        ).replace(
            "p.name AS project_name,",
            "p.code AS project_code,\n  p.name AS project_name,",
            1,
        )
        rows = matcher.query_mysql_rows(connection, sql)
        raw_candidate_count += len(rows)
        lookup_mode = "script-content" if script_expression == matcher.SCRIPT_CONTENT_EXPR else "task-params"
        lookup_modes.append(lookup_mode)
        for row in rows:
            script_content = normalize_path(row.get("script_content") or row.get("sql_content") or "")
            matched_item = None
