"""Resolve a DolphinScheduler resource file back to tasks that reference it.

This script runs on the country jump host.  It reuses the already deployed
read-only DS candidate helper for MySQL connection discovery, then performs one
bounded metadata query against current workflow/task definitions.
"""

from __future__ import annotations

import argparse
import base64
import importlib.util
import json
import os
import sys
from pathlib import Path
from typing import Any


def emit(success: bool, data: Any = None, error: Any = None) -> None:
    print(
        json.dumps(
            {
                "success": success,
                "country": os.environ.get("COUNTRY_CODE", ""),
                "action": "find_resource_usage",
                "request_id": os.environ.get("REQUEST_ID", ""),
                "data": data,
                "error": error,
            },
            ensure_ascii=False,
        )
    )


def decode_payload() -> dict[str, Any]:
    value = os.environ.get("PAYLOAD_B64", "").strip()
    if not value:
        return {}
    decoded = base64.b64decode(value.encode("utf-8"), validate=False).decode("utf-8", errors="replace")
    result = json.loads(decoded)
    return result if isinstance(result, dict) else {}


def load_matcher() -> Any:
    configured = Path(os.environ.get("DS_MATCH_SCRIPT", "")).expanduser()
    candidates = [
        configured,
        Path("/tmp/KN-YCGJ-TZ-governance-automation/alert-sql-notification/governance-automation/remote_scripts/ds_match_candidate_query.py"),
        Path("/root/KN-YCGJ-TZ/alert-sql-notification/governance-automation/remote_scripts/ds_match_candidate_query.py"),
    ]
    script = next((path for path in candidates if path.is_file()), None)
    if not script:
        raise RuntimeError("DS_MATCH_CODE_NOT_DEPLOYED: run candidate workflow deployment once")
    spec = importlib.util.spec_from_file_location("ds_match_candidate_query_for_resource_usage", script)
    if not spec or not spec.loader:
        raise RuntimeError(f"cannot import DS matcher: {script}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def normalize_path(value: str) -> str:
    return str(value or "").strip().replace("\\", "/").lower()


def build_terms(payload: dict[str, Any]) -> list[str]:
    full_name = normalize_path(payload.get("full_name") or payload.get("resource_full_name") or "")
    file_name = normalize_path(payload.get("file_name") or payload.get("resource_name") or "")
    if full_name and not file_name:
        file_name = full_name.rsplit("/", 1)[-1]
    terms: list[str] = []
    for value in (full_name, full_name.lstrip("/"), file_name):
        if value and len(value) >= 3 and value not in terms:
            terms.append(value)
    return terms


def sql_like_literal(value: str) -> str:
    escaped = str(value or "").replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_").replace("'", "''")
    return escaped


def reference_matches(text: str, terms: list[str]) -> tuple[bool, str]:
    normalized = normalize_path(text)
    for term in terms:
        if term in normalized:
            return True, term
    return False, ""


def main() -> None:
    try:
        payload = decode_payload()
        terms = build_terms(payload)
        if not terms:
            emit(False, error={"code": "RESOURCE_PATH_REQUIRED", "message": "full_name or file_name is required"})
            return

        matcher = load_matcher()
        args = argparse.Namespace(
            ds_db_host="",
            ds_db_port="",
            ds_db_user="",
            ds_db_password="",
            ds_db_name="",
        )
        pid = ""
        process_env: dict[str, str] = {}
        try:
            pid = matcher.find_ds_pid()
            process_env = matcher.read_process_env(pid)
            connection = matcher.discover_ds_mysql_connection(args, process_env)
        except Exception as discover_error:
            configured = matcher.configured_ds_mysql_connection(os.environ.get("COUNTRY_CODE", ""))
            if not configured:
                raise discover_error
            connection = configured

        max_results = max(1, min(int(payload.get("max_results") or 20), 100))
        query_limit = min(max(max_results * 5, 20), 500)
        matches: list[dict[str, Any]] = []
        seen: set[tuple[str, str, str]] = set()
        rows: list[dict[str, Any]] = []
        raw_candidate_count = 0
        lookup_modes: list[str] = []
        matched_lookup_mode = ""
        script_expressions = []
        for expression in (matcher.SCRIPT_CONTENT_EXPR, "COALESCE(td.task_params, '')"):
            if expression and expression not in script_expressions:
                script_expressions.append(expression)
        for script_expression in script_expressions:
            clauses = [
                f"LOWER({script_expression}) LIKE '%{sql_like_literal(term)}%' ESCAPE '\\\\'"
                for term in terms
            ]
            script_filter_sql = "AND (" + " OR ".join(clauses) + ")"
            sql = matcher.DS_TASK_CANDIDATE_SQL_TEMPLATE.format(
                limit=query_limit,
                script_content_expr=script_expression,
                script_filter_sql=script_filter_sql,
            ).replace(
                "p.name AS project_name,",
                "p.code AS project_code,\n  p.name AS project_name,",
                1,
            )
            rows = matcher.query_mysql_rows(connection, sql)
            raw_candidate_count += len(rows)
            lookup_mode = "script-content" if script_expression == matcher.SCRIPT_CONTENT_EXPR else "task-params"
            lookup_modes.append(lookup_mode)
            for row in rows:
                content = str(row.get("script_content") or row.get("sql_content") or "")
                matched, matched_term = reference_matches(content, terms)
                if not matched:
                    continue
                key = (
                    str(row.get("project_code") or row.get("project_name") or ""),
                    str(row.get("workflow_code") or row.get("workflow_name") or ""),
                    str(row.get("task_code") or row.get("task_name") or ""),
                )
                if key in seen:
                    continue
                seen.add(key)
                matches.append(
                    {
                        "project_code": str(row.get("project_code") or ""),
                        "project_name": str(row.get("project_name") or ""),
                        "workflow_code": str(row.get("workflow_code") or ""),
                        "workflow_name": str(row.get("workflow_name") or ""),
                        "task_code": str(row.get("task_code") or ""),
                        "task_name": str(row.get("task_name") or ""),
                        "task_type": str(row.get("task_type") or ""),
                        "task_flag": str(row.get("task_flag") or ""),
                        "matched_resource": matched_term,
                        "resource_full_name": terms[0],
                        "resource_lookup_mode": lookup_mode,
                    }
                )
                if len(matches) >= max_results:
                    break
            if matches or len(matches) >= max_results:
                matched_lookup_mode = lookup_mode
                break

        emit(
            True,
            {
                "items": matches,
                "matched_usage_count": len(matches),
                "resource_full_name": terms[0],
                "searched_terms": terms,
                "raw_candidate_count": raw_candidate_count,
                "ds_pid": pid,
                "lookup_modes": lookup_modes,
                "matched_lookup_mode": matched_lookup_mode,
                "truncated": len(matches) >= max_results,
            },
        )
    except Exception as error:
        emit(False, error={"code": "RESOURCE_USAGE_LOOKUP_FAILED", "message": str(error) or repr(error)})


if __name__ == "__main__":
    main()
DS_RESOURCE_USAGE_LOOKUP_PY
elif [ "$ACTION" = "search_country_git_sql" ]; then
  GIT_ROOT='/data/git/starrocks/workflow/ph'
  export COUNTRY_CODE ACTION REQUEST_ID PAYLOAD_B64 GIT_ROOT
  python3 - <<'COUNTRY_GIT_SEARCH_PY'
import base64
import json
import os
import re
import shutil
import subprocess
import sys
import time
from pathlib import Path


MAX_SEARCH_FILES = 30
MAX_READ_FILES = 6
MAX_FILE_BYTES = 1_000_000
MAX_CONTENT_CHARS = 20_000
MAX_PYTHON_SCANNED_FILES = 2_000
RG_SEARCH_TIMEOUT_SECONDS = 4
SEARCH_BUDGET_SECONDS = 8
SEARCH_DEADLINE = time.monotonic() + SEARCH_BUDGET_SECONDS
ALLOWED_SUFFIXES = {".sql", ".hql", ".py", ".sh", ".bash", ".txt"}


def text(value):
    return "" if value is None else str(value)


def normalize_sql(value):
    value = re.sub(r"--[^\n]*", " ", text(value))
    value = re.sub(r"/\*[\s\S]*?\*/", " ", value)
    value = re.sub(r"\$\{[^}]+\}", ":var", value)
    value = re.sub(r"\{\{[^}]+\}\}", ":var", value)
    value = value.lower().replace("`", "").replace('"', "")
    return " ".join(value.split()).strip()


def normalize_template(value):
    value = normalize_sql(value)
    value = re.sub(r"\b\d{4}-\d{2}-\d{2}(?:[ t]\d{2}:\d{2}:\d{2})?\b", ":date", value)
    value = re.sub(r"\b[0-9a-f]{8}-[0-9a-f-]{27}\b", ":uuid", value, flags=re.I)
    value = re.sub(r"'[^']*'", ":str", value)
    value = re.sub(r"\b\d+(?:\.\d+)?\b", ":num", value)
    return value


def extract_tables(value):
    normalized = normalize_sql(value)
    cte_names = {
        match.group(1).lower()
        for match in re.finditer(r"(?:\bwith|,)\s*([a-zA-Z_][\w]*)\s+as\s*\(", normalized, flags=re.I)
    }
    ignored = {"select", "table", "values", "if", "exists", "as", "where"}
    tables = set()
    for match in re.finditer(r"\b(?:from|join|into|overwrite|update|table)\s+([a-zA-Z_][\w.]*)", normalized, flags=re.I):
        table = match.group(1).strip("`\"")
        if table and table not in ignored and table.lower() not in cte_names:
            tables.add(table)
    return sorted(tables)


def overlap(left, right):
    left = set(left)
    right = set(right)
    if not left or not right:
        return 0.0
    return len(left & right) / len(left | right)


def compare_sql(source_sql, content):
    source_norm = normalize_sql(source_sql)
    content_norm = normalize_sql(content)
    source_template = normalize_template(source_sql)
    content_template = normalize_template(content)
    exact = bool(source_norm and content_norm and source_norm == content_norm)
    template_exact = bool(not exact and source_template and content_template and source_template == content_template)
    contains = bool(len(source_norm) >= 80 and content_norm and (source_norm in content_norm or content_norm in source_norm))
    template_contains = bool(
        len(source_template) >= 80
        and content_template
        and (source_template in content_template or content_template in source_template)
    )
    source_tables = extract_tables(source_sql)
    content_tables = extract_tables(content)
    table_overlap = overlap(source_tables, content_tables)
    score = 0
    if exact:
        score += 160
    elif template_exact:
        score += 140
    elif contains:
        score += 120
    elif template_contains:
        score += 110
    score += round(table_overlap * 50)
    return {
        "exact": exact,
        "template_exact": template_exact,
        "contains": contains,
        "template_contains": template_contains,
        "source_tables": source_tables,
        "content_tables": content_tables,
        "table_overlap": round(table_overlap, 4),
        "score": score,
    }


def candidate_sql(row):
    for key in (
        "sql_content",
        "sqlContent",
        "stmt",
        "script_content",
        "raw_script",
        "sql_text",
        "script_text",
        "statement_text",
        "resource_list",
        "script",
        "log_sql",
        "sql_excerpt",
        "sqlSnippet",
    ):
        value = row.get(key)
        if value:
            return text(value)
    return ""


def old_sql_resolved(rows, source_sql):
    for row in rows:
        confidence = text(row.get("ds_match_confidence") or row.get("ds_match_confidence_level")).strip().lower()
        info = text(row.get("ds_match_remote_info") or row.get("ds_match_info")).strip().lower()
        has_location = bool(row.get("project_name") or row.get("workflow_name") or row.get("task_name"))
        if has_location and confidence in {"high", "medium"} and info != "no-match":
            return True
        sql = candidate_sql(row)
        if not sql:
            continue
        comparison = compare_sql(source_sql, sql)
        if comparison["exact"] or comparison["template_exact"] or comparison["contains"] or comparison["template_contains"]:
            return True
    return False


GIT_SEARCH_ACCOUNTS = {"e_load", "e_ds_strategy"}


def request_accounts():
    accounts = {text(os.environ.get("PRIMARY_ACCOUNT", "")).strip().lower()}
    try:
        raw_hints = json.loads(os.environ.get("ACCOUNT_HINTS_JSON", "[]"))
        if isinstance(raw_hints, list):
            accounts.update(text(value).strip().lower() for value in raw_hints)
    except (TypeError, ValueError):
        pass
    return {value for value in accounts if value}


def is_git_search_account():
    return bool(request_accounts() & GIT_SEARCH_ACCOUNTS)


def collect_candidate_strings(value, depth=0, seen=None):
    if seen is None:
        seen = set()
    if value is None or depth > 8:
        return []
    if isinstance(value, (str, int, float)):
        return [str(value)]
    if not isinstance(value, (dict, list)) or id(value) in seen:
        return []
    seen.add(id(value))
    values = []
    children = value if isinstance(value, list) else value.values()
    for child in children:
        values.extend(collect_candidate_strings(child, depth + 1, seen))
        if len(values) >= 200:
            break
    return values[:200]


def candidate_file_terms(rows):
    terms = set()
    for row in rows:
        for value in collect_candidate_strings(row):
            for match in re.findall(r"(?:^|[/\s'\"])([\w.-]+\.(?:sql|hql|py|sh|bash))(?:$|[\s'\"])", value, flags=re.I):
                if len(match) >= 4:
                    terms.add(match)
    return terms


def sql_search_terms(source_sql):
    terms = []
    seen = set()
    for raw_line in text(source_sql).splitlines():
        line = " ".join(raw_line.split()).strip()
        if len(line) < 16:
            continue
        if not re.search(r"\b(?:create|insert|select|from|join|where|group\s+by|update|delete)\b", line, flags=re.I):
            continue
        line = line[:240]
        lowered = line.lower()
        if lowered not in seen:
            seen.add(lowered)
            terms.append(line)
    for table in extract_tables(source_sql):
        if table.lower() not in seen:
            seen.add(table.lower())
            terms.append(table)
    return terms[:4]


def find_files_with_rg(root, terms):
    rg = shutil.which("rg")
    if not rg:
        return []
    paths = []
    seen = set()
    for term in terms:
        if time.monotonic() >= SEARCH_DEADLINE:
            break
        command = [
            rg,
            "-l",
            "--fixed-strings",
            "--no-messages",
            "--glob",
            "*.sql",
            "--glob",
            "*.hql",
            "--glob",
            "*.py",
            "--glob",
            "*.sh",
            "--glob",
            "*.bash",
            term,
            str(root),
        ]
        try:
            remaining = max(0.2, SEARCH_DEADLINE - time.monotonic())
            result = subprocess.run(
                command,
                capture_output=True,
                text=True,
                timeout=min(RG_SEARCH_TIMEOUT_SECONDS, remaining),
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired):
            continue
        for raw_path in result.stdout.splitlines():
            path = Path(raw_path).resolve()
            try:
                path.relative_to(root)
            except ValueError:
                continue
            if path not in seen and path.is_file():
                seen.add(path)
                paths.append(path)
                if len(paths) >= MAX_SEARCH_FILES:
                    return paths
    return paths


def find_files_with_python(root, source_sql, terms):
    lowered_terms = [term.lower() for term in terms if term]
    if not lowered_terms:
        return []
    paths = []
    scanned = 0
    for path in root.rglob("*"):
        if (
            len(paths) >= MAX_SEARCH_FILES
            or scanned >= MAX_PYTHON_SCANNED_FILES
            or time.monotonic() >= SEARCH_DEADLINE
        ):
            break
        if not path.is_file() or path.suffix.lower() not in ALLOWED_SUFFIXES:
            continue
        scanned += 1
        try:
            if path.stat().st_size > MAX_FILE_BYTES:
                continue
            content = path.read_text(encoding="utf-8", errors="ignore").lower()
        except OSError:
            continue
        comparison = compare_sql(source_sql, content)
        sql_matched = bool(
            comparison["exact"]
            or comparison["template_exact"]
            or comparison["contains"]
            or comparison["template_contains"]
            or comparison["table_overlap"] > 0
        )
        if sql_matched or any(term in content or term in path.name.lower() for term in lowered_terms):
            paths.append(path.resolve())
    return paths


def read_evidence(root, paths, source_sql):
    evidence = []
    for path in paths[:MAX_READ_FILES]:
        if time.monotonic() >= SEARCH_DEADLINE:
            break
        try:
            if path.stat().st_size > MAX_FILE_BYTES:
                continue
            content = path.read_text(encoding="utf-8", errors="ignore")[:MAX_CONTENT_CHARS]
            relative_path = path.relative_to(root).as_posix()
        except (OSError, ValueError):
            continue
        comparison = compare_sql(source_sql, content)
        if comparison["score"] <= 0:
            continue
        evidence.append(
            {
                "source_type": "country_git_file_search",
                "country": os.environ.get("COUNTRY_CODE", ""),
                "root": str(root),
                "path": relative_path,
                "full_path": str(path),
                "content": content,
                **comparison,
            }
        )
    return sorted(evidence, key=lambda row: (-row["score"], row["path"]))


def attach_evidence(rows, evidence):
    for row in rows:
        candidate_text = "\n".join(collect_candidate_strings(row)).lower()
        attached = []
        for item in evidence[:10]:
            path = item.get("path", "")
            file_name = Path(path).name.lower()
            linked = bool(file_name and file_name in candidate_text) or bool(path and path.lower() in candidate_text)
            source_type = "country_git_file_linked" if linked else "country_git_file_search"
            attached.append({**item, "source_type": source_type, "linked_to_task": linked})
        row["country_git_evidence"] = attached[:5]
        row["country_git_best"] = attached[0] if attached else None
        row["country_git_search_ok"] = True


def strong_sql_evidence(item):
    return bool(
        item.get("exact")
        or item.get("template_exact")
        or item.get("contains")
        or item.get("template_contains")
        or float(item.get("table_overlap") or 0) >= 0.8
    )


