        meta["country_git_search"] = "skipped"
        meta["country_git_search_reason"] = "git-root-not-found"
        print(json.dumps(result, ensure_ascii=False))
        return

    terms, paths, evidence, search_engine = search_country_git(root, source_sql)
    result["country_git_evidence"] = evidence[:5]
