    usage_evidence = [item for item in evidence if strong_sql_evidence(item)]
    usage_rows = []
    usage_meta = {"raw_candidate_count": 0, "ds_pid": ""}
    if usage_evidence:
        try:
            usage_rows, usage_meta = resolve_evidence_usage(usage_evidence)
        except Exception as usage_error:
            meta["country_git_usage_error"] = str(usage_error) or repr(usage_error)
    if usage_rows:
        existing_keys = {
            (
                text(row.get("project_code") or row.get("project_name")),
                text(row.get("workflow_code") or row.get("workflow_name")),
                text(row.get("task_code") or row.get("task_name")),
            )
            for row in rows
        }
        for usage_row in usage_rows:
            key = (
                text(usage_row.get("project_code") or usage_row.get("project_name")),
                text(usage_row.get("workflow_code") or usage_row.get("workflow_name")),
                text(usage_row.get("task_code") or usage_row.get("task_name")),
            )
            if key not in existing_keys:
                rows.append(usage_row)
                existing_keys.add(key)
        meta["match_info"] = "country-git-usage-match"
        meta["confidence"] = "high" if len(usage_rows) == 1 else "medium"
    meta["country_git_search"] = "ok"
    meta["country_git_search_engine"] = search_engine
    meta["country_git_search_mode"] = "full-sql-with-fragment-prefilter"
    meta["country_git_search_terms"] = terms
    meta["country_git_file_count"] = len(paths)
    meta["country_git_evidence_count"] = len(evidence)
    meta["country_git_strong_evidence_count"] = len(usage_evidence)
    meta["country_git_usage_count"] = len(usage_rows)
    meta["country_git_usage_raw_candidate_count"] = usage_meta.get("raw_candidate_count", 0)
    meta["country_git_usage_ds_pid"] = usage_meta.get("ds_pid", "")
    meta["country_git_usage_lookup_modes"] = usage_meta.get("lookup_modes", [])
    meta["country_git_usage_matched_lookup_mode"] = usage_meta.get("matched_lookup_mode", "")
    meta["country_git_search_accounts"] = sorted(GIT_SEARCH_ACCOUNTS)
    result["data"] = rows
    result["candidate_count"] = len(rows)
    print(json.dumps(result, ensure_ascii=False))


