    ]
    script = next((path for path in candidates if path.is_file()), None)
    if not script:
        raise RuntimeError("DS_MATCH_CODE_NOT_DEPLOYED")
    import importlib.util

    spec = importlib.util.spec_from_file_location("ds_match_candidate_query_for_country_git", script)
    if not spec or not spec.loader:
        raise RuntimeError(f"cannot import DS matcher: {script}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def discover_matcher_connection(matcher):
