def normalize_path(value):
    return text(value).strip().replace("\\", "/").lower()


def sql_like_literal(value):
    return text(value).replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_").replace("'", "''")


def evidence_reference_terms(item):
    full_path = normalize_path(item.get("full_path") or item.get("path") or "")
    relative_path = normalize_path(item.get("path") or "")
    file_name = Path(full_path or relative_path).name.lower()
    terms = []
    for value in (full_path, relative_path, file_name):
        if value and len(value) >= 4 and value not in terms:
            terms.append(value)
    return terms


def resolve_evidence_usage(evidence, max_results=20):
    if not evidence:
        return [], {"raw_candidate_count": 0, "ds_pid": ""}
    matcher = load_matcher()
    connection, pid = discover_matcher_connection(matcher)
    matches = []
    seen = set()
    evidence_terms = []
    all_terms = []
    for item in evidence[:MAX_READ_FILES]:
        terms = evidence_reference_terms(item)
        if terms:
            evidence_terms.append((item, terms))
            for term in terms:
                if term not in all_terms:
                    all_terms.append(term)
    if not all_terms:
        return [], {"raw_candidate_count": 0, "ds_pid": pid}
    query_limit = min(max(max_results * 20, 200), 500)
    script_expressions = []
    for expression in (matcher.SCRIPT_CONTENT_EXPR, "COALESCE(td.task_params, '')"):
        if expression and expression not in script_expressions:
            script_expressions.append(expression)
    raw_candidate_count = 0
    lookup_modes = []
    for script_expression in script_expressions:
        clauses = [
            f"LOWER({script_expression}) LIKE '%{sql_like_literal(term)}%' ESCAPE '\\\\'"
            for term in all_terms
        ]
        script_filter_sql = "AND (" + " OR ".join(clauses) + ")"
        sql = matcher.DS_TASK_CANDIDATE_SQL_TEMPLATE.format(
            limit=query_limit,
            script_content_expr=script_expression,
            script_filter_sql=script_filter_sql,
        ).replace(
            "p.name AS project_name,",
            "p.code AS project_code,\n  p.name AS project_name,",
            1,
        )
        rows = matcher.query_mysql_rows(connection, sql)
        raw_candidate_count += len(rows)
        lookup_mode = "script-content" if script_expression == matcher.SCRIPT_CONTENT_EXPR else "task-params"
        lookup_modes.append(lookup_mode)
        for row in rows:
            script_content = normalize_path(row.get("script_content") or row.get("sql_content") or "")
            matched_item = None
            matched_term = ""
            for item, terms in evidence_terms:
                matched_term = next((term for term in terms if term in script_content), "")
                if matched_term:
                    matched_item = item
                    break
            if not matched_item:
                continue
            item = matched_item
            key = (
                text(row.get("project_code") or row.get("project_name")),
                text(row.get("workflow_code") or row.get("workflow_name")),
                text(row.get("task_code") or row.get("task_name")),
            )
            if key in seen:
                continue
            seen.add(key)
            linked_evidence = {
                **item,
                "source_type": "country_git_file_linked",
                "linked_to_task": True,
                "matched_resource": matched_term,
                "resource_lookup_mode": lookup_mode,
            }
            matches.append(
                {
                    **row,
                    "project_code": text(row.get("project_code")),
                    "project_name": text(row.get("project_name")),
                    "workflow_code": text(row.get("workflow_code")),
                    "workflow_name": text(row.get("workflow_name")),
                    "task_code": text(row.get("task_code")),
                    "task_name": text(row.get("task_name")),
                    "sql_content": item.get("content") or "",
                    "country_git_evidence": [linked_evidence],
                    "country_git_best": linked_evidence,
                    "country_git_search_ok": True,
                    "ds_match_confidence": "high",
                    "ds_match_remote_info": "country-git-resource-reference",
                    "ds_match_strategy": "country-git-file-usage",
                    "country_git_usage_lookup_mode": lookup_mode,
                }
            )
            if len(matches) >= max_results:
                break
        if matches or len(matches) >= max_results:
            break
    return matches, {
        "raw_candidate_count": raw_candidate_count,
        "ds_pid": pid,
        "lookup_modes": lookup_modes,
        "matched_lookup_mode": matches[0].get("country_git_usage_lookup_mode", "") if matches else "",
    }


def decode_router_payload():
    value = text(os.environ.get("PAYLOAD_B64", "")).strip()
    if not value:
        return {}
    decoded = base64.b64decode(value.encode("utf-8"), validate=False).decode("utf-8", errors="replace")
    payload = json.loads(decoded)
    return payload if isinstance(payload, dict) else {}


def search_country_git(root, source_sql):
    terms = sql_search_terms(source_sql)
    paths = find_files_with_rg(root, terms)
    search_engine = "rg"
    if not paths:
        paths = find_files_with_python(root, source_sql, terms)
        search_engine = "python-full-sql-fallback"
    evidence = read_evidence(root, paths, source_sql)
    if not evidence and search_engine == "rg" and time.monotonic() < SEARCH_DEADLINE:
        fallback_paths = find_files_with_python(root, source_sql, terms)
        if fallback_paths:
            paths = fallback_paths
            evidence = read_evidence(root, paths, source_sql)
            search_engine = "rg-then-python-full-sql"
    return terms, paths, evidence, search_engine


def run_router_search(country, root):
    try:
        payload = decode_router_payload()
        source_sql = text(payload.get("sql_query") or payload.get("sql") or "").strip()
        if not source_sql:
            raise ValueError("sql_query or sql is required")
        if not root.is_dir():
            raise FileNotFoundError(f"country git root not found: {root}")
        terms, paths, evidence, search_engine = search_country_git(root, source_sql)
        max_results = max(1, min(int(payload.get("max_results") or 6), 20))
        print(
            json.dumps(
                {
                    "success": True,
                    "country": country,
                    "action": "search_country_git_sql",
                    "request_id": os.environ.get("REQUEST_ID", ""),
                    "data": {
                        "items": evidence[:max_results],
                        "matched_file_count": len(evidence),
                        "candidate_file_count": len(paths),
                        "search_engine": search_engine,
                        "search_mode": "full-sql-with-fragment-prefilter",
                        "search_terms": terms,
                        "country_git_root": str(root),
                    },
                    "error": None,
                },
                ensure_ascii=False,
            )
        )
    except Exception as error:
        print(
            json.dumps(
                {
                    "success": False,
                    "country": country,
                    "action": "search_country_git_sql",
                    "request_id": os.environ.get("REQUEST_ID", ""),
                    "data": {"items": []},
                    "error": {"code": "COUNTRY_GIT_SEARCH_FAILED", "message": str(error) or repr(error)},
                },
                ensure_ascii=False,
            )
        )


def main():
    country = os.environ.get("COUNTRY_CODE", "").strip().lower()
    root = Path(os.environ.get("GIT_ROOT", f"/data/git/starrocks/workflow/{country}")).resolve()
    if os.environ.get("ACTION", "").strip() == "search_country_git_sql":
        run_router_search(country, root)
        return

    result_path = Path(os.environ["DS_RESULT_FILE"])
    try:
        result = json.loads(result_path.read_text(encoding="utf-8"))
    except Exception as error:
        print(json.dumps({"success": False, "data": [], "error": {"code": "INVALID_DS_RESULT", "message": str(error)}}))
        return

    meta = result.get("meta") if isinstance(result.get("meta"), dict) else {}
    result["meta"] = meta
    meta["country_git_root"] = str(root)
    rows = result.get("data") if isinstance(result.get("data"), list) else []

    if not is_git_search_account():
        meta["country_git_search"] = "skipped"
        meta["country_git_search_reason"] = "account-not-git-search-whitelist"
        meta["country_git_search_accounts"] = sorted(GIT_SEARCH_ACCOUNTS)
        print(json.dumps(result, ensure_ascii=False))
        return

    try:
        source_sql = base64.b64decode(os.environ.get("SQL_TEXT_B64", "")).decode("utf-8", errors="ignore")
    except Exception:
        source_sql = ""
    if not source_sql:
        meta["country_git_search"] = "skipped"
        meta["country_git_search_reason"] = "source-sql-missing"
        print(json.dumps(result, ensure_ascii=False))
        return

    if old_sql_resolved(rows, source_sql):
        meta["country_git_search"] = "skipped"
        meta["country_git_search_reason"] = "old-sql-resolved"
        print(json.dumps(result, ensure_ascii=False))
        return

    if not root.is_dir():
        meta["country_git_search"] = "skipped"
        meta["country_git_search_reason"] = "git-root-not-found"
        print(json.dumps(result, ensure_ascii=False))
        return

    terms, paths, evidence, search_engine = search_country_git(root, source_sql)
    result["country_git_evidence"] = evidence[:5]
    attach_evidence(rows, evidence)
    usage_evidence = [item for item in evidence if strong_sql_evidence(item)]
    usage_rows = []
    usage_meta = {"raw_candidate_count": 0, "ds_pid": ""}
    if usage_evidence:
        try:
            usage_rows, usage_meta = resolve_evidence_usage(usage_evidence)
        except Exception as usage_error:
            meta["country_git_usage_error"] = str(usage_error) or repr(usage_error)
    if usage_rows:
        existing_keys = {
            (
                text(row.get("project_code") or row.get("project_name")),
                text(row.get("workflow_code") or row.get("workflow_name")),
                text(row.get("task_code") or row.get("task_name")),
            )
            for row in rows
        }
        for usage_row in usage_rows:
            key = (
                text(usage_row.get("project_code") or usage_row.get("project_name")),
                text(usage_row.get("workflow_code") or usage_row.get("workflow_name")),
                text(usage_row.get("task_code") or usage_row.get("task_name")),
            )
            if key not in existing_keys:
                rows.append(usage_row)
                existing_keys.add(key)
        meta["match_info"] = "country-git-usage-match"
        meta["confidence"] = "high" if len(usage_rows) == 1 else "medium"
    meta["country_git_search"] = "ok"
    meta["country_git_search_engine"] = search_engine
    meta["country_git_search_mode"] = "full-sql-with-fragment-prefilter"
    meta["country_git_search_terms"] = terms
    meta["country_git_file_count"] = len(paths)
    meta["country_git_evidence_count"] = len(evidence)
    meta["country_git_strong_evidence_count"] = len(usage_evidence)
    meta["country_git_usage_count"] = len(usage_rows)
    meta["country_git_usage_raw_candidate_count"] = usage_meta.get("raw_candidate_count", 0)
