"""Resolve a DolphinScheduler resource file back to tasks that reference it.

This script runs on the country jump host.  It reuses the already deployed
read-only DS candidate helper for MySQL connection discovery, then performs one
bounded metadata query against current workflow/task definitions.
"""

from __future__ import annotations

import argparse
import base64
import importlib.util
import json
import os
import sys
from pathlib import Path
from typing import Any


def emit(success: bool, data: Any = None, error: Any = None) -> None:
    print(
        json.dumps(
            {
                "success": success,
                "country": os.environ.get("COUNTRY_CODE", ""),
                "action": "find_resource_usage",
                "request_id": os.environ.get("REQUEST_ID", ""),
                "data": data,
                "error": error,
            },
            ensure_ascii=False,
        )
    )


def decode_payload() -> dict[str, Any]:
    value = os.environ.get("PAYLOAD_B64", "").strip()
    if not value:
        return {}
    decoded = base64.b64decode(value.encode("utf-8"), validate=False).decode("utf-8", errors="replace")
    result = json.loads(decoded)
    return result if isinstance(result, dict) else {}


def load_matcher() -> Any:
    configured = Path(os.environ.get("DS_MATCH_SCRIPT", "")).expanduser()
    candidates = [
        configured,
        Path("/tmp/KN-YCGJ-TZ-governance-automation/alert-sql-notification/governance-automation/remote_scripts/ds_match_candidate_query.py"),
        Path("/root/KN-YCGJ-TZ/alert-sql-notification/governance-automation/remote_scripts/ds_match_candidate_query.py"),
    ]
    script = next((path for path in candidates if path.is_file()), None)
    if not script:
        raise RuntimeError("DS_MATCH_CODE_NOT_DEPLOYED: run candidate workflow deployment once")
    spec = importlib.util.spec_from_file_location("ds_match_candidate_query_for_resource_usage", script)
    if not spec or not spec.loader:
        raise RuntimeError(f"cannot import DS matcher: {script}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def normalize_path(value: str) -> str:
    return str(value or "").strip().replace("\\", "/").lower()


def build_terms(payload: dict[str, Any]) -> list[str]:
    full_name = normalize_path(payload.get("full_name") or payload.get("resource_full_name") or "")
    file_name = normalize_path(payload.get("file_name") or payload.get("resource_name") or "")
    if full_name and not file_name:
        file_name = full_name.rsplit("/", 1)[-1]
    terms: list[str] = []
    for value in (full_name, full_name.lstrip("/"), file_name):
        if value and len(value) >= 3 and value not in terms:
            terms.append(value)
    return terms


def sql_like_literal(value: str) -> str:
    escaped = str(value or "").replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_").replace("'", "''")
    return escaped


def reference_matches(text: str, terms: list[str]) -> tuple[bool, str]:
    normalized = normalize_path(text)
    for term in terms:
        if term in normalized:
            return True, term
    return False, ""


def main() -> None:
    try:
        payload = decode_payload()
        terms = build_terms(payload)
        if not terms:
            emit(False, error={"code": "RESOURCE_PATH_REQUIRED", "message": "full_name or file_name is required"})
            return

        matcher = load_matcher()
        args = argparse.Namespace(
            ds_db_host="",
