        except Exception as discover_error:
            configured = matcher.configured_ds_mysql_connection(os.environ.get("COUNTRY_CODE", ""))
            if not configured:
                raise discover_error
            connection = configured

        max_results = max(1, min(int(payload.get("max_results") or 20), 100))
        query_limit = min(max(max_results * 5, 20), 500)
        matches: list[dict[str, Any]] = []
        seen: set[tuple[str, str, str]] = set()
        rows: list[dict[str, Any]] = []
        raw_candidate_count = 0
        lookup_modes: list[str] = []
        matched_lookup_mode = ""
        script_expressions = []
        for expression in (matcher.SCRIPT_CONTENT_EXPR, "COALESCE(td.task_params, '')"):
            if expression and expression not in script_expressions:
