            rows = matcher.query_mysql_rows(connection, sql)
            raw_candidate_count += len(rows)
            lookup_mode = "script-content" if script_expression == matcher.SCRIPT_CONTENT_EXPR else "task-params"
            lookup_modes.append(lookup_mode)
            for row in rows:
                content = str(row.get("script_content") or row.get("sql_content") or "")
                matched, matched_term = reference_matches(content, terms)
                if not matched:
                    continue
                key = (
