                        "resource_lookup_mode": lookup_mode,
                    }
                )
                if len(matches) >= max_results:
                    break
            if matches or len(matches) >= max_results:
                matched_lookup_mode = lookup_mode
                break

        emit(
            True,
            {
                "items": matches,
                "matched_usage_count": len(matches),
                "resource_full_name": terms[0],
                "searched_terms": terms,
                "raw_candidate_count": raw_candidate_count,
