    for script_expression in script_expressions:
        clauses = [
            f"LOWER({script_expression}) LIKE '%{sql_like_literal(term)}%' ESCAPE '\\\\'"
            for term in all_terms
        ]
        script_filter_sql = "AND (" + " OR ".join(clauses) + ")"
        sql = matcher.DS_TASK_CANDIDATE_SQL_TEMPLATE.format(
            limit=query_limit,
            script_content_expr=script_expression,
            script_filter_sql=script_filter_sql,
        ).replace(
            "p.name AS project_name,",
            "p.code AS project_code,\n  p.name AS project_name,",
            1,
        )
        rows = matcher.query_mysql_rows(connection, sql)
        raw_candidate_count += len(rows)
        lookup_mode = "script-content" if script_expression == matcher.SCRIPT_CONTENT_EXPR else "task-params"
        lookup_modes.append(lookup_mode)
        for row in rows:
            script_content = normalize_path(row.get("script_content") or row.get("sql_content") or "")
            matched_item = None
            matched_term = ""
            for item, terms in evidence_terms:
                matched_term = next((term for term in terms if term in script_content), "")
                if matched_term:
                    matched_item = item
                    break
            if not matched_item:
                continue
            item = matched_item
            key = (
                text(row.get("project_code") or row.get("project_name")),
                text(row.get("workflow_code") or row.get("workflow_name")),
                text(row.get("task_code") or row.get("task_name")),
            )
            if key in seen:
                continue
            seen.add(key)
            linked_evidence = {
                **item,
                "source_type": "country_git_file_linked",
                "linked_to_task": True,
                "matched_resource": matched_term,
                "resource_lookup_mode": lookup_mode,
            }
            matches.append(
                {
                    **row,
                    "project_code": text(row.get("project_code")),
                    "project_name": text(row.get("project_name")),
                    "workflow_code": text(row.get("workflow_code")),
                    "workflow_name": text(row.get("workflow_name")),
                    "task_code": text(row.get("task_code")),
                    "task_name": text(row.get("task_name")),
                    "sql_content": item.get("content") or "",
                    "country_git_evidence": [linked_evidence],
                    "country_git_best": linked_evidence,
                    "country_git_search_ok": True,
                    "ds_match_confidence": "high",
                    "ds_match_remote_info": "country-git-resource-reference",
                    "ds_match_strategy": "country-git-file-usage",
                    "country_git_usage_lookup_mode": lookup_mode,
                }
            )
            if len(matches) >= max_results:
                break
        if matches or len(matches) >= max_results:
            break
    return matches, {
        "raw_candidate_count": raw_candidate_count,
        "ds_pid": pid,
        "lookup_modes": lookup_modes,
        "matched_lookup_mode": matches[0].get("country_git_usage_lookup_mode", "") if matches else "",
    }


def decode_router_payload():
    value = text(os.environ.get("PAYLOAD_B64", "")).strip()
    if not value:
        return {}
    decoded = base64.b64decode(value.encode("utf-8"), validate=False).decode("utf-8", errors="replace")
    payload = json.loads(decoded)
    return payload if isinstance(payload, dict) else {}


def search_country_git(root, source_sql):
    terms = sql_search_terms(source_sql)
    paths = find_files_with_rg(root, terms)
    search_engine = "rg"
    if not paths:
        paths = find_files_with_python(root, source_sql, terms)
        search_engine = "python-full-sql-fallback"
    evidence = read_evidence(root, paths, source_sql)
    if not evidence and search_engine == "rg" and time.monotonic() < SEARCH_DEADLINE:
        fallback_paths = find_files_with_python(root, source_sql, terms)
        if fallback_paths:
            paths = fallback_paths
            evidence = read_evidence(root, paths, source_sql)
            search_engine = "rg-then-python-full-sql"
    return terms, paths, evidence, search_engine


def run_router_search(country, root):
    try:
        payload = decode_router_payload()
        source_sql = text(payload.get("sql_query") or payload.get("sql") or "").strip()
        if not source_sql:
            raise ValueError("sql_query or sql is required")
        if not root.is_dir():
            raise FileNotFoundError(f"country git root not found: {root}")
        terms, paths, evidence, search_engine = search_country_git(root, source_sql)
        max_results = max(1, min(int(payload.get("max_results") or 6), 20))
        print(
            json.dumps(
                {
                    "success": True,
                    "country": country,
                    "action": "search_country_git_sql",
                    "request_id": os.environ.get("REQUEST_ID", ""),
                    "data": {
                        "items": evidence[:max_results],
                        "matched_file_count": len(evidence),
                        "candidate_file_count": len(paths),
                        "search_engine": search_engine,
                        "search_mode": "full-sql-with-fragment-prefilter",
                        "search_terms": terms,
                        "country_git_root": str(root),
                    },
                    "error": None,
                },
                ensure_ascii=False,
            )
        )
    except Exception as error:
        print(
            json.dumps(
