MAX_CONTENT_CHARS = 20_000
MAX_PYTHON_SCANNED_FILES = 2_000
RG_SEARCH_TIMEOUT_SECONDS = 4
SEARCH_BUDGET_SECONDS = 8
SEARCH_DEADLINE = time.monotonic() + SEARCH_BUDGET_SECONDS
ALLOWED_SUFFIXES = {".sql", ".hql", ".py", ".sh", ".bash", ".txt"}


def text(value):
    return "" if value is None else str(value)


def normalize_sql(value):
    value = re.sub(r"--[^\n]*", " ", text(value))
    value = re.sub(r"/\*[\s\S]*?\*/", " ", value)
    value = re.sub(r"\$\{[^}]+\}", ":var", value)
    value = re.sub(r"\{\{[^}]+\}\}", ":var", value)
    value = value.lower().replace("`", "").replace('"', "")
    return " ".join(value.split()).strip()


def normalize_template(value):
    value = normalize_sql(value)
    value = re.sub(r"\b\d{4}-\d{2}-\d{2}(?:[ t]\d{2}:\d{2}:\d{2})?\b", ":date", value)
    value = re.sub(r"\b[0-9a-f]{8}-[0-9a-f-]{27}\b", ":uuid", value, flags=re.I)
    value = re.sub(r"'[^']*'", ":str", value)
    value = re.sub(r"\b\d+(?:\.\d+)?\b", ":num", value)
    return value


def extract_tables(value):
    normalized = normalize_sql(value)
    cte_names = {
        match.group(1).lower()
        for match in re.finditer(r"(?:\bwith|,)\s*([a-zA-Z_][\w]*)\s+as\s*\(", normalized, flags=re.I)
    }
    ignored = {"select", "table", "values", "if", "exists", "as", "where"}
    tables = set()
    for match in re.finditer(r"\b(?:from|join|into|overwrite|update|table)\s+([a-zA-Z_][\w.]*)", normalized, flags=re.I):
        table = match.group(1).strip("`\"")
        if table and table not in ignored and table.lower() not in cte_names:
            tables.add(table)
    return sorted(tables)


def overlap(left, right):
    left = set(left)
    right = set(right)
    if not left or not right:
        return 0.0
    return len(left & right) / len(left | right)


def compare_sql(source_sql, content):
    source_norm = normalize_sql(source_sql)
    content_norm = normalize_sql(content)
    source_template = normalize_template(source_sql)
    content_template = normalize_template(content)
    exact = bool(source_norm and content_norm and source_norm == content_norm)
    template_exact = bool(not exact and source_template and content_template and source_template == content_template)
    contains = bool(len(source_norm) >= 80 and content_norm and (source_norm in content_norm or content_norm in source_norm))
    template_contains = bool(
        len(source_template) >= 80
        and content_template
        and (source_template in content_template or content_template in source_template)
    )
    source_tables = extract_tables(source_sql)
    content_tables = extract_tables(content)
    table_overlap = overlap(source_tables, content_tables)
    score = 0
    if exact:
        score += 160
    elif template_exact:
        score += 140
    elif contains:
        score += 120
    elif template_contains:
        score += 110
    score += round(table_overlap * 50)
    return {
        "exact": exact,
        "template_exact": template_exact,
        "contains": contains,
        "template_contains": template_contains,
        "source_tables": source_tables,
        "content_tables": content_tables,
        "table_overlap": round(table_overlap, 4),
        "score": score,
    }


def candidate_sql(row):
    for key in (
        "sql_content",
        "sqlContent",
        "stmt",
        "script_content",
        "raw_script",
