def decode_router_payload():
    value = text(os.environ.get("PAYLOAD_B64", "")).strip()
    if not value:
        return {}
    decoded = base64.b64decode(value.encode("utf-8"), validate=False).decode("utf-8", errors="replace")
    payload = json.loads(decoded)
    return payload if isinstance(payload, dict) else {}


def search_country_git(root, source_sql):
    terms = sql_search_terms(source_sql)
