}
const fallbackCtx = {
  source: upstream.source || 'codex-skill',
  country: upstream.country || response.country || '',
  action: upstream.action || response.action || '',
  request_id: upstream.request_id || response.request_id || '',
  ds_token: typeof upstream.ds_token === 'string' ? upstream.ds_token : '',
  payload: upstream.payload && typeof upstream.payload === 'object' ? upstream.payload : {},
