};
const incomingCtx = response.audit_context && typeof response.audit_context === 'object' ? response.audit_context : {};
const hasPayload = incomingCtx.payload && typeof incomingCtx.payload === 'object' && Object.keys(incomingCtx.payload).length > 0;
const ctx = {
  source: incomingCtx.source || fallbackCtx.source,
  country: incomingCtx.country || fallbackCtx.country,
  action: incomingCtx.action || fallbackCtx.action,
  request_id: incomingCtx.request_id || fallbackCtx.request_id,
  ds_token: typeof incomingCtx.ds_token === 'string' && incomingCtx.ds_token
