};
const errorObj = response.error && typeof response.error === 'object' ? response.error : null;
const now = new Date();
const startedAtMs = Number(ctx.started_at_ms || 0);
const durationMs = startedAtMs > 0 ? Math.max(0, now.getTime() - startedAtMs) : null;

const riskActions = new Set([
  'create_workflow',
  'create_schedule',
  'update_schedule',
  'batch_update_schedule_alerts',
  'online_schedule',
  'offline_schedule',
  'online_workflow',
  'offline_workflow',
  'trigger_workflow',
  'retry_instance',
  'append_task',
  'append_sql_task',
  'append_shell_task',
  'update_task',
  'update_sql_task',
  'update_shell_task',
  'disable_tasks_except',
  'disable_task',
  'delete_task',
]);

const highRiskActions = new Set([
  'delete_task',
  'disable_tasks_except',
  'disable_task',
  'offline_schedule',
  'offline_workflow',
]);

function detectTargetType(action, body) {
  if (body.task_instance_id) return 'task_instance';
  if (body.instance_id || body.process_instance_id) return 'instance';
  if (body.task_code || body.task_name) return 'task';
  if (body.schedule_id) return 'schedule';
  if (body.workflow_code || body.workflow_name) return 'workflow';
  if (body.project_code) return 'project';
  if (action === 'list_datasources' || action === 'get_datasource') return 'datasource';
  return 'unknown';
}

function detectRiskLevel(action) {
  if (highRiskActions.has(action)) return 'high';
  if (riskActions.has(action)) return 'medium';
  return 'low';
}

function shellQuote(value) {
  const text = String(value ?? '');
  return "'" + text.replace(/'/g, "'\"'\"'") + "'";
}

function sqlQuote(value) {
  const text = String(value ?? '');
  return "'" + text
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "''")
    .replace(/\u0000/g, '\\0')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t')
    .replace(/\u0008/g, '\\b')
    .replace(/\u000c/g, '\\f') + "'";
}

function encodeJsonBase64(value) {
  return Buffer.from(JSON.stringify(value ?? null), 'utf8').toString('base64');
}

function shellEscapeForRemote(value) {
  const text = String(value ?? '');
  return "'" + text.replace(/'/g, "'\\''") + "'";
}

const success = !!response.success;
const action = String(response.action || ctx.action || '').trim();
const targetType = detectTargetType(action, payload);
const riskLevel = detectRiskLevel(action);
const errorCode = errorObj && errorObj.code ? String(errorObj.code) : '';
