};

const bt = String.fromCharCode(96);
const sql = [
  'INSERT INTO ds_operation_audit_log (',
  'request_id, trace_id, ' + bt + 'operator' + bt + ', source_system, country, action, target_type,',
  'project_code, workflow_code, workflow_name, schedule_id, task_code, task_name,',
