const begin = '__AUDIT_JSON_BEGIN__';
const end = '__AUDIT_JSON_END__';
const start = stdout.indexOf(begin);
const finish = stdout.indexOf(end);
if (start < 0 || finish < 0 || finish <= start) {
  return [{
    json: {
      audit_ok: false,
      audit_error: {
        code: 'AUDIT_MARKER_NOT_FOUND',
        message: '未找到审计写入结果标记',
